  async sendFormConfirmation(submission) {
    if (Workflows.getActive()) {
      const result = await this.engine.handleFormSubmit(submission);
      if (result.handled) return;
    }

    const { buildLeadVars, renderTemplate } = require('../utils/leadSummary');
    const vars = buildLeadVars(submission);
    const template = Settings.get('confirmation_template');
    const text = renderTemplate(template, vars);
    try {
      await this.sendMessage(submission.customer_phone, text);
    } catch (err) {
      console.error('[WhatsApp] Legacy confirmation send failed:', err.message);
    }
  }

  async confirmAndForward(submission, opts = {}) {
    // Prefer shared forward path (logging + non-fatal desk errors)
    await this.engine.forwardLeadToDesk(submission, {
      phone: submission.customer_phone,
      chatId: opts.chatId,
      replyTo: opts.replyTo,
    });
  }
}

module.exports = new WhatsAppService();

old_string:
  async sendFormConfirmation(submission) {
    if (Workflows.getActive()) {
      const result = await this.engine.handleFormSubmit(submission);
      if (result.handled) return;
    }

    const extra = safeParse(submission.extra_data);
    const template = Settings.get('confirmation_template');
    const text = this.renderTemplate(template, {
      name: submission.customer_name,
      insurance_type: submission.insurance_type,
      company: submission.company,
      phone: submission.customer_phone,
      details: formatExtraDetails(extra, submission.insurance_type),
    });
    await this.sendMessage(submission.customer_phone, text);
  }

  async confirmAndForward(submission, opts = {}) {
    Submissions.markConfirmed(submission.id);
    const target = InternalNumbers.resolveForType(submission.insurance_type);
    if (!target) {
      await this.sendMessage(
        submission.customer_phone,
        'Your details are confirmed, but no internal desk number is configured yet. Our admin will follow up shortly.',
        opts
      );
      return;
    }

    const extra = safeParse(submission.extra_data);
    const forwardText = this.renderTemplate(Settings.get('forward_template'), {
      name: submission.customer_name,
      phone: submission.customer_phone,
      insurance_type: submission.insurance_type,
      company: submission.company,
      submitted_at: submission.form_submitted_at || new Date().toISOString(),
      details: formatExtraDetails(extra, submission.insurance_type),
    });
    await this.sendMessage(target.phone, forwardText);
    Submissions.markForwarded(submission.id, target.phone);
    await this.sendMessage(submission.customer_phone, Settings.get('success_message'), opts);
  }
}

function safeParse(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;
  try { return JSON.parse(raw); } catch (_) { return {}; }
}

function formatExtraDetails(extra, type) {
  if (!extra || typeof extra !== 'object') return '';
  const lines = [];
  const t = String(type || '').toLowerCase();
  if (t === 'health') {
    if (extra.member_count) lines.push(`• Members: ${extra.member_count}`);
    if (extra.coverage_amount) lines.push(`• Coverage: ${extra.coverage_amount}`);
    if (Array.isArray(extra.members) && extra.members.length) {
      extra.members.forEach((m, i) => {
        lines.push(`  Member ${i + 1}: ${m.name || '—'} | DOB: ${m.dob || '—'} | ${m.gender || '—'}`);
      });
    }
    if (extra.age && !extra.members) lines.push(`• Age: ${extra.age}`);
    if (extra.existing_illnesses && !extra.members) lines.push(`• Existing illnesses: ${extra.existing_illnesses}`);
  } else if (t === 'vehicle') {
    if (extra.vehicle_model) lines.push(`• Vehicle: ${extra.vehicle_model}`);
    if (extra.manufacturing_year) lines.push(`• Year: ${extra.manufacturing_year}`);
    if (extra.policy_type) lines.push(`• Policy type: ${extra.policy_type}`);
  }
  return lines.join('\n');
}

module.exports = new WhatsAppService();
